24: FUNC_INLINE __u64 cgroup_get_parent_id(struct cgroup *cgrp)
25: {
26: 	struct cgroup___new *cgrp_new = (struct cgroup___new *)cgrp;
27: 
28: 	// for newer kernels, we can access use ->ancestors to retrieve the parent
29: 	if (bpf_core_field_exists(cgrp_new->ancestors)) {
30: 		int level = get_cgroup_level(cgrp);
31: 
32: 		if (level <= 0)
33: 			return 0;
34: 		return BPF_CORE_READ(cgrp_new, ancestors[level - 1], kn, id);
35: 	}
36: 
37: 	// otherwise, go over the parent pointer
38: 	struct cgroup_subsys_state *parent_css = BPF_CORE_READ(cgrp, self.parent);
39: 
40: 	if (parent_css) {
41: 		struct cgroup *parent = container_of(parent_css, struct cgroup, self);
42: 		__u64 parent_cgid = get_cgroup_id(parent);
43: 		return parent_cgid;
44: 	}
45: 
46: 	return 0;
47: }
